/// 16 - Lock screen preview of the lifecycle push sequence generated by
/// [PushScheduler]. Tapping a card deep-links like the real notification.
class PushSequenceScreen extends ConsumerWidget {
  const PushSequenceScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final seq = ref.watch(pushSequenceProvider);
    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(fit: StackFit.expand, children: [
        Image.asset(Img.lockWallpaper, fit: BoxFit.cover),
        Container(color: Colors.black.withValues(alpha: .18)),
        SafeArea(
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Column(children: [
              Row(children: [
                IconButton(onPressed: () => Nav.pop(), icon: const Icon(Icons.close_rounded, color: Colors.white)),
                const Spacer(),
              ]),
              const Icon(Icons.lock_outline_rounded, color: Colors.white, size: 22),
              const SizedBox(height: 6),
              Text(DateFormat('EEEE, MMMM d').format(kNow),
                  style: const TextStyle(color: Colors.white, fontSize: 20, fontWeight: FontWeight.w600)),
              const SizedBox(height: 10),
              const Text('8:00',
                  style: TextStyle(
                      color: Colors.white, fontSize: 76, fontWeight: FontWeight.w800, height: 1.1, letterSpacing: -2)),
              const Spacer(),
              if (seq.isEmpty)
                const _LockCard(
                  title: 'Notifications are off',
                  body: 'Turn on reminders in Settings to get your sequence',
                  time: '',
                )
              else
                for (final (i, m) in seq.indexed) ...[
                  _LockCard(
                    title: m.title,
                    body: m.body,
                    time: i == 0 ? 'now' : DateFormat('h:mm a').format(m.at),
                    actions: i == 0 ? m.actions : const [],
                    onTap: () => m.kind == PushKind.trial ? Nav.trialEnding() : Nav.today(),
                    onAction: (a) {
                      if (a == 'Done') ref.read(doneProvider.notifier).toggle('d3');
                      Nav.today();
                    },
                  ),
                  const SizedBox(height: 8),
                ],
              const SizedBox(height: 6),
              const Row(children: [
                _RoundGlass(Icons.flashlight_on_outlined),
                Spacer(),
                Text('Swipe up to unlock', style: TextStyle(color: Colors.white70, fontSize: 15)),
                Spacer(),
                _RoundGlass(Icons.photo_camera_outlined),
              ]),
              const SizedBox(height: 10),
            ]),
          ),
        ),
      ]),
    );
  }
}

class _LockCard extends StatelessWidget {
  const _LockCard(
      {required this.title,
      required this.body,
      required this.time,
      this.actions = const [],
      this.onTap,
      this.onAction});
  final String title;
  final String body;
  final String time;
  final List<String> actions;
  final VoidCallback? onTap;
  final ValueChanged<String>? onAction;

  @override
  Widget build(BuildContext context) => GestureDetector(
        onTap: onTap,
        child: Container(
          width: double.infinity,
          padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
          decoration:
              BoxDecoration(color: Colors.white.withValues(alpha: .86), borderRadius: BorderRadius.circular(22)),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              ClipRRect(
                borderRadius: BorderRadius.circular(7),
                child: Container(
                  width: 26,
                  height: 26,
                  color: AppColors.accentFill,
                  padding: const EdgeInsets.all(3),
                  child: const Icon(Icons.spa_outlined, color: Colors.white, size: 18),
                ),
              ),
              const SizedBox(width: 8),
              const Text('DailyDose', style: TextStyle(fontWeight: FontWeight.w700, fontSize: 15)),
              const Spacer(),
              Text(time, style: AppText.caption),
            ]),
            const SizedBox(height: 6),
            Text(title, style: AppText.label.copyWith(fontSize: 16)),
            Text(body, style: AppText.bodyMuted.copyWith(fontSize: 15)),
            if (actions.isNotEmpty) ...[
              const SizedBox(height: 10),
              Row(children: [
                for (final (i, a) in actions.indexed) ...[
                  Expanded(
                    child: SizedBox(
                      height: 40,
                      child: FilledButton(
                        onPressed: () => onAction?.call(a),
                        style: FilledButton.styleFrom(
                          backgroundColor: i == 0 ? AppColors.accentFill : Colors.white,
                          foregroundColor: i == 0 ? Colors.white : AppColors.textPrimary,
                          shape: const StadiumBorder(),
                        ),
                        child: Text(a, style: const TextStyle(fontWeight: FontWeight.w700)),
                      ),
                    ),
                  ),
                  if (i < actions.length - 1) const SizedBox(width: 10),
                ],
              ]),
            ],
          ]),
        ),
      );
}

class _RoundGlass extends StatelessWidget {
  const _RoundGlass(this.icon);
  final IconData icon;

  @override
  Widget build(BuildContext context) => Container(
        width: 54,
        height: 54,
        decoration: BoxDecoration(color: Colors.black.withValues(alpha: .35), shape: BoxShape.circle),
        child: Icon(icon, color: Colors.white),
      );
}

/// 17 - Daily check-in, opened from the 8 PM push.
class CheckInScreen extends ConsumerWidget {
  const CheckInScreen({super.key});

  static const moods = [
    (Mood.great, 'Great', Icons.sentiment_very_satisfied_outlined),
    (Mood.good, 'Good', Icons.sentiment_satisfied_alt_outlined),
    (Mood.okay, 'Okay', Icons.sentiment_neutral_outlined),
    (Mood.tired, 'Tired', Icons.bedtime_outlined),
    (Mood.rough, 'Rough', Icons.sentiment_dissatisfied_outlined),
  ];

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final draft = ref.watch(checkInDraftProvider);
    final reminders = ref.watch(remindersProvider);
    final done = ref.watch(doneProvider);
    final n = reminders.where((r) => done.contains(r.id)).length;
    final setDraft = ref.read(checkInDraftProvider.notifier);
    return Scaffold(
      body: SafeArea(
        child: Column(children: [
          Expanded(
            child: ListView(padding: const EdgeInsets.fromLTRB(20, 4, 20, 12), children: [
              Row(children: [
                IconButton(onPressed: () => Nav.pop(), icon: const Icon(Icons.close_rounded)),
                Expanded(
                  child: Column(children: [
                    const Text('Daily check-in', style: AppText.title),
                    Text('Evening check-in, ${DateFormat('EEE MMM d').format(kNow)}', style: AppText.caption),
                  ]),
                ),
                const SizedBox(width: 48),
              ]),
              const SizedBox(height: 16),
              const Text('How did today go, $kUserName?', style: AppText.headline),
              const SizedBox(height: 4),
              const Text('Reflect on your routine and wind down for the night.', style: AppText.bodyMuted),
              const SizedBox(height: 16),
              AppCard(
                padding: const EdgeInsets.all(16),
                child: Column(children: [
                  SectionLabel('How are you feeling?',
                      trailing: Text('Selected: ${moods.firstWhere((m) => m.$1 == draft.mood).$2}',
                          style: const TextStyle(color: AppColors.accentFill, fontWeight: FontWeight.w600))),
                  Row(children: [
                    for (final m in moods)
                      Expanded(
                        child: GestureDetector(
                          onTap: () => setDraft.state = draft.copyWith(mood: m.$1),
                          child: AnimatedContainer(
                            duration: const Duration(milliseconds: 180),
                            margin: const EdgeInsets.symmetric(horizontal: 3),
                            padding: const EdgeInsets.symmetric(vertical: 12),
                            decoration: BoxDecoration(
                              color: draft.mood == m.$1 ? AppColors.accentFill : AppColors.surfaceAlt,
                              borderRadius: BorderRadius.circular(16),
                            ),
                            child: Column(children: [
                              Icon(m.$3, color: draft.mood == m.$1 ? Colors.white : AppColors.accentFill, size: 26),
                              const SizedBox(height: 6),
                              Text(m.$2,
                                  style: TextStyle(
                                      fontSize: 13,
                                      fontWeight: FontWeight.w700,
                                      color: draft.mood == m.$1 ? Colors.white : AppColors.textSecondary)),
                            ]),
                          ),
                        ),
                      ),
                  ]),
                ]),
              ),
              const SizedBox(height: 14),
              AppCard(
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
                child: Column(children: [
                  Row(children: [
                    const Icon(Icons.bolt_rounded, color: AppColors.accentFill),
                    const SizedBox(width: 6),
                    const Text('Energy level', style: AppText.label),
                    const Spacer(),
                    Pill('${draft.energy}/10', dense: true),
                  ]),
                  Slider(
                    value: draft.energy.toDouble(),
                    min: 1,
                    max: 10,
                    divisions: 9,
                    activeColor: AppColors.accent,
                    inactiveColor: AppColors.surfaceAlt,
                    onChanged: (v) => setDraft.state = draft.copyWith(energy: v.round()),
                  ),
                ]),
              ),
              const SizedBox(height: 14),
              AppCard(
                padding: const EdgeInsets.fromLTRB(16, 16, 16, 6),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    const Text("Today's routine", style: AppText.title),
                    const Spacer(),
                    Text('${(n * 100 / reminders.length).round()}% done',
                        style: const TextStyle(color: AppColors.accent, fontWeight: FontWeight.w800)),
                  ]),
                  Text('$n of ${reminders.length} completed', style: AppText.caption),
                  const SizedBox(height: 6),
                  for (final r in reminders)
                    Padding(
                      padding: const EdgeInsets.symmetric(vertical: 8),
                      child: Row(children: [
                        CheckCircle(
                            done: done.contains(r.id),
                            size: 28,
                            onTap: () => ref.read(doneProvider.notifier).toggle(r.id)),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Text(r.title,
                              style: AppText.label.copyWith(
                                  fontSize: 15,
                                  color: done.contains(r.id) ? AppColors.textTertiary : AppColors.textPrimary,
                                  decoration: done.contains(r.id) ? TextDecoration.lineThrough : null)),
                        ),
                        done.contains(r.id)
                            ? Text(fmtTime(r.time), style: AppText.caption)
                            : OutlinedButton(
                                onPressed: () => ref.read(doneProvider.notifier).toggle(r.id),
                                style: OutlinedButton.styleFrom(
                                    foregroundColor: AppColors.accentFill,
                                    side: const BorderSide(color: AppColors.accentFill),
                                    shape: const StadiumBorder(),
                                    visualDensity: VisualDensity.compact),
                                child: const Text('Mark done', style: TextStyle(fontWeight: FontWeight.w700)),
                              ),
                      ]),
                    ),
                ]),
              ),
            ]),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 0, 20, 8),
            child: Column(children: [
              PrimaryButton('Complete check-in', trailingArrow: true, onTap: () => completeCheckIn(ref)),
              const SizedBox(height: 8),
              Text('Streak will update to Day ${ref.watch(streakProvider) + 1}', style: AppText.caption),
            ]),
          ),
        ]),
      ),
    );
  }
}

void completeCheckIn(WidgetRef ref) {
  final d = ref.read(checkInDraftProvider);
  ref.read(checkInsProvider.notifier).state = [
    ...ref.read(checkInsProvider),
    CheckIn(date: kNow, mood: d.mood, energy: d.energy, note: d.note),
  ];
  ref.read(streakProvider.notifier).state++;
  final reminders = ref.read(remindersProvider);
  final done = ref.read(doneProvider);
  ref.read(analyticsProvider).capture(Ev.checkInCompleted, {
    'mood': d.mood.name,
    'energy': d.energy,
    'routine_done': '${reminders.where((r) => done.contains(r.id)).length}/${reminders.length}',
    'streak': ref.read(streakProvider),
  });
  Nav.checkInComplete();
}

/// 18 - Check-in complete: celebrate streak, plan tomorrow, soft Plus upsell.
class CheckInCompleteScreen extends ConsumerWidget {
  const CheckInCompleteScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final streak = ref.watch(streakProvider);
    final prefs = ref.watch(notificationPrefsProvider);
    final tomorrow = ref.watch(remindersProvider).where((r) => r.time.hour < 12).take(2).toList();
    return Scaffold(
      body: SafeArea(
        child: Column(children: [
          Expanded(
            child: ListView(padding: const EdgeInsets.fromLTRB(20, 4, 20, 12), children: [
              Row(children: [
                IconButton(onPressed: () => Nav.backToRoot(), icon: const Icon(Icons.close_rounded)),
                const Expanded(child: Center(child: Text('Daily routine', style: AppText.title))),
                const SizedBox(width: 48),
              ]),
              const SizedBox(height: 10),
              AppCard(
                gradient: AppColors.heroGradient,
                child: Column(children: [
                  const Pill('Check-in complete', dense: true, icon: Icons.local_fire_department_outlined),
                  const SizedBox(height: 10),
                  Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      crossAxisAlignment: CrossAxisAlignment.end,
                      children: [
                        Text('$streak', style: AppText.display.copyWith(fontSize: 96, height: 1)),
                        const SizedBox(width: 8),
                        const Padding(
                          padding: EdgeInsets.only(bottom: 12),
                          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            Icon(Icons.local_fire_department_outlined, color: AppColors.accent, size: 34),
                            Text('day', style: AppText.title),
                            Text('streak', style: AppText.caption),
                          ]),
                        ),
                      ]),
                  const Divider(height: 28, color: AppColors.border),
                  Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                    for (final d in const ['M', 'T', 'W', 'T', 'F', 'S', 'S'])
                      Column(children: [
                        Text(d, style: AppText.caption),
                        const SizedBox(height: 6),
                        const CircleAvatar(
                            radius: 18,
                            backgroundColor: AppColors.accent,
                            child: Icon(Icons.check_rounded, color: Colors.white, size: 20)),
                      ]),
                  ]),
                  const SizedBox(height: 12),
                  Text('You checked in $streak days in a row', style: AppText.bodyMuted),
                ]),
              ),
              const SizedBox(height: 14),
              AppCard(
                child: Column(children: [
                  Row(children: [
                    const Text('Tomorrow', style: AppText.title),
                    const Spacer(),
                    Text('${tomorrow.length} scheduled', style: AppText.caption),
                  ]),
                  const SizedBox(height: 10),
                  for (final r in tomorrow)
                    Container(
                      margin: const EdgeInsets.only(bottom: 8),
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(color: AppColors.surfaceAlt, borderRadius: BorderRadius.circular(14)),
                      child: Row(children: [
                        CircleIcon(
                            r.kind == ReminderKind.workout ? Icons.directions_walk_rounded : Icons.medication_outlined,
                            bg: Colors.white,
                            size: 40),
                        const SizedBox(width: 12),
                        Expanded(child: Text(r.name, style: AppText.label.copyWith(fontSize: 16))),
                        Text(fmtTime(r.time), style: AppText.label),
                      ]),
                    ),
                  const Divider(height: 18, color: AppColors.border),
                  Row(children: [
                    const Icon(Icons.notifications_active_outlined, color: AppColors.textSecondary),
                    const SizedBox(width: 10),
                    Expanded(
                        child: Text('Remind me at ${fmtTime(prefs.checkInTime)} to check in', style: AppText.label)),
                    Switch(
                      value: prefs.dailyCheckIn,
                      onChanged: (v) =>
                          ref.read(notificationPrefsProvider.notifier).state = prefs.copyWith(dailyCheckIn: v),
                    ),
                  ]),
                ]),
              ),
              const SizedBox(height: 14),
              GestureDetector(
                onTap: () => Nav.paywall(),
                child: const AppCard(
                  padding: EdgeInsets.all(16),
                  child: Row(children: [
                    CircleIcon(Icons.insights_rounded, bg: AppColors.supportTint),
                    SizedBox(width: 12),
                    Expanded(child: Text('Unlock your weekly insights with DailyDose Plus', style: AppText.label)),
                    Icon(Icons.chevron_right_rounded, color: AppColors.textTertiary),
                  ]),
                ),
              ),
            ]),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 0, 20, 8),
            child: Column(children: [
              PrimaryButton('Done', onTap: () => Nav.backToRoot()),
              TextAction('Share my streak', color: AppColors.accentFill),
            ]),
          ),
        ]),
      ),
    );
  }
}
